H.background();
const k = 8.99e9;
const q1 = P.q1; // microcoulombs
const q2 = P.q2;
const r = Math.max(P.r, 0.1); // meters
// Force magnitude in newtons: q in microC -> 1e-6
const F = k * Math.abs(q1 * q2) * 1e-12 / (r * r);
const repel = q1 * q2 > 0;
H.text("Coulomb's law: F = k q1 q2 / r^2", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Like charges repel, opposite attract; F falls off as 1/r^2 (k = 8.99e9 N m^2/C^2)", 24, 52, { color: H.colors.sub, size: 13 });
const cy = 300;
// map r (0.1..5 m) to pixel separation
const sepMax = 320;
const rNorm = Math.min(r / 5, 1);
const sep = 60 + sepMax * rNorm;
const cx = 450;
// small oscillation showing the push/pull tendency
const osc = 8 * Math.sin(t * 1.6);
const x1 = cx - sep / 2 - (repel ? -osc : osc);
const x2 = cx + sep / 2 + (repel ? -osc : osc);
// charge 1
const c1 = q1 >= 0 ? H.colors.warn : H.colors.accent;
const c2 = q2 >= 0 ? H.colors.warn : H.colors.accent;
H.circle(x1, cy, 22, { fill: c1, stroke: H.colors.ink, width: 2 });
H.text((q1 >= 0 ? "+" : "-"), x1, cy, { color: "#0e1525", size: 22, align: "center", baseline: "middle", weight: 700 });
H.text("q1 = " + q1.toFixed(1) + " uC", x1, cy - 36, { color: c1, size: 13, align: "center" });
H.circle(x2, cy, 22, { fill: c2, stroke: H.colors.ink, width: 2 });
H.text((q2 >= 0 ? "+" : "-"), x2, cy, { color: "#0e1525", size: 22, align: "center", baseline: "middle", weight: 700 });
H.text("q2 = " + q2.toFixed(1) + " uC", x2, cy - 36, { color: c2, size: 13, align: "center" });
// force arrows on each charge (Newton's third law: equal & opposite)
const aL = 50;
if (repel) {
  H.arrow(x1, cy + 40, x1 - aL, cy + 40, { color: H.colors.good, width: 3 });
  H.arrow(x2, cy + 40, x2 + aL, cy + 40, { color: H.colors.good, width: 3 });
  H.text("REPEL", cx, cy + 70, { color: H.colors.good, size: 13, align: "center", weight: 700 });
} else {
  H.arrow(x1, cy + 40, x1 + aL, cy + 40, { color: H.colors.violet, width: 3 });
  H.arrow(x2, cy + 40, x2 - aL, cy + 40, { color: H.colors.violet, width: 3 });
  H.text("ATTRACT", cx, cy + 70, { color: H.colors.violet, size: 13, align: "center", weight: 700 });
}
// distance marker
H.line(x1, cy - 60, x2, cy - 60, { color: H.colors.sub, width: 1, dash: [4, 4] });
H.text("r = " + r.toFixed(2) + " m", cx, cy - 68, { color: H.colors.sub, size: 12, align: "center" });
H.text("F = " + F.toExponential(2) + " N  (on each charge)", 24, 96, { color: H.colors.good, size: 14, weight: 700 });
